	(3, 'prueba', 'prueba', 'prueba', 'prueba', 'prueba', 'Servicio', 'Borrador', NULL, 1548, '2026-11-03 16:43:43', '2026-11-03 16:43:43'),
	(4, 'prueba', 'prueba', 'prueba', 'prueba', 'prueba', 'Servicio', 'En edición', NULL, 1548, '2026-11-03 16:44:32', '2026-11-03 19:30:07');
INSERT INTO `cn-requerimiento-documento` (`id`, `doc_contenido_html`, `doc_version`, `doc_pdf_path`, `doc_generado_at`, `req_id`, `created_at`, `updated_at`) VALUES
	(1, '<h1 style="text-align:center;">TÉRMINOS DE REFERENCIA</h1>\n<p style="text-align:center;"><strong>SERVICIO</strong></p>\n\n<h2>1. DENOMINACIÓN DE LA CONTRATACIÓN</h2>\n<p>prueba</p>\n\n<h2>2. FINALIDAD PÚBLICA</h2>\n<p>prueba</p>\n\n<h2>3. DESCRIPCIÓN GENERAL DEL REQUERIMIENTO</h2>\n<p>prueba</p>\n\n<h2>4. OBJETIVO DE LA CONTRATACIÓN</h2>\n<p>prueba</p>\n\n<h2>5. ANTECEDENTES DE LA CONTRATACIÓN</h2>\n<p>prueba</p>\n\n<h2>6. ALCANCE Y ACTIVIDADES</h2>\n<p>[Describir el alcance, las actividades y las condiciones técnicas que deberá cumplir el contratista.]</p>\n\n<h2>7. CARACTERÍSTICAS Y CONDICIONES DEL REQUERIMIENTO</h2>\n<p>[Completar las especificaciones técnicas, características, cantidades, unidades de medida o condiciones del servicio, según corresponda.]</p>\n\n<h2>8. ENTREGABLES</h2>\n<p>[Indicar los productos, informes o entregables, su contenido y oportunidad de presentación.]</p>\n\n<h2>9. PLAZO DE EJECUCIÓN</h2>\n<p>[Indicar el plazo de ejecución y el momento desde el cual se computa.]</p>\n\n<h2>10. LUGAR DE PRESTACIÓN O ENTREGA</h2>\n<p>[Indicar la ubicación o lugar donde se ejecutará la prestación o se entregarán los bienes.]</p>\n\n<h2>11. PERFIL Y REQUISITOS DEL PROVEEDOR</h2>\n<p>[Completar los requisitos mínimos, experiencia y calificaciones que correspondan y estén debidamente sustentados.]</p>\n\n<h2>12. CONFORMIDAD</h2>\n<p>[Indicar el área o responsable que emitirá la conformidad y los criterios para otorgarla.]</p>\n\n<h2>13. FORMA Y CONDICIONES DE PAGO</h2>\n<p>[Indicar la modalidad, oportunidad y condiciones de pago, de acuerdo con las reglas aplicables.]</p>\n\n<h2>14. PENALIDADES</h2>\n<p>[Completar las penalidades aplicables conforme al marco normativo y las condiciones de la contratación.]</p>\n\n<h2>15. RESPONSABILIDAD POR VICIOS OCULTOS</h2>\n<p>[Completar el plazo y condiciones de responsabilidad, cuando corresponda.]</p>\n\n<h2>16. CONFIDENCIALIDAD Y PROTECCIÓN DE INFORMACIÓN</h2>\n<p>[Indicar las obligaciones de confidencialidad y protección de información, si corresponde.]</p>\n\n<h2>17. SEGURIDAD Y SALUD EN EL TRABAJO / MEDIO AMBIENTE</h2>\n<p>[Incorporar las obligaciones aplicables a la naturaleza de la prestación.]</p>\n\n<h2>18. OTRAS CONDICIONES</h2>\n<p>[Agregar otras condiciones necesarias para la correcta ejecución de la contratación.]</p>\n', '1', NULL, NULL, NULL, '2026-11-03 16:43:43', '2026-11-03 16:43:43'),
