INSERT INTO `items` (`id`, `item_nombre`, `item_detalle`, `item_medida`, `item_cantidad`, `item_alternativo`, `item_fproducto`, `item_cotizacion`, `created_at`, `updated_at`) VALUES
	(1, 'SELLADOR HIDRAULICO CEMENTICIO DE RAPIDO FRAGUADO', '- Base Químico: Cemento Portland.\r\n- Presentación: Lata de 1.7 kg.\r\n- Uso: sellar filtraciones de agua en grietas y perforaciones en estructuras de concreto, albañilería o roca.', 34, 6, 0, 1, 1, '2024-07-13 00:15:02', '2024-07-13 00:22:27'),
	(2, 'HERBICIDA', '- Ingrediente activo: Glyphosate\r\n- Concentración: 480 g/L\r\n- Formulación: Concentrado Soluble\r\n- Clase de uso: Herbicida Agrícola\r\n- Grupo Químico: Glycines', 34, 12, 0, 1, 2, '2024-07-13 00:23:29', '2024-07-13 00:26:30'),
	(3, 'VENTILADOR RADIAL CENTRÍFUGO DE 22 x 22', '- >Características técnicas:\r\n- Tipo de turbina De acción\r\n- Alabes Curvados hacia atrás\r\n- Diámetro máximo de la turbina 586 mm\r\n- Diámetro del eje de la turbina 1 3/8\r\n- Revoluciones máximas 900 RPM\r\n- Eficiencia mínima 65%\r\n- Transmisión motor\r\n- turbina Poleas con correas\r\n>Condiciones de operación:\r\n- Altitud 1465 msnm\r\n- Caudal mínimo requerido 20 000 m^3/h\r\n- Temperatura de aire en la central 20°C\r\n>Características de motor eléctrico:\r\n- Potencia: De acuerdo con lo indicado en tablas para las condiciones dadas\r\n- Tensión 380 VCA\r\n- Frecuencia 60 Hz\r\n>Equipos incluidos en la oferta:\r\n- Turbina\r\n- Motor eléctrico\r\n- Poleas\r\n- Fajas de transmisión\r\n- Estructura de soporte de conjunto', 34, 2, 1, 1, 3, '2024-07-13 00:30:20', '2024-07-18 01:51:33'),
	(4, 'UN (01) INSTRUCTOR PARA LA IMPLEMENTACIÓN DEL PROGRAMA DE INTERVENCIÓN DE SALUD EN TERAPIA FÍSICA Y REHABILITACIÓN, EN LA SEDE ADMINISTRATIVA DE PUNO.', '- Se realizará una (01) sesión por mes.', 30, 6, 0, 0, 4, '2024-07-13 01:47:31', '2024-07-15 15:16:42'),
	(5, 'UN (01) INSTRUCTOR PARA LA IMPLEMENTACIÓN DEL PROGRAMA DE INTERVENCIÓN DE SALUD EN TERAPIA FÍSICA Y REHABILITACIÓN, EN LA SEDE VILLA DE RESIDENTES DE LA C.H. SAN GABÁN II.', '- DATO REFERENCIAL: Se podrá realizar de una (01) a dos (02) sesiones por mes.', 30, 12, 0, 0, 4, '2024-07-13 01:47:31', '2024-07-15 15:16:42'),
