INSERT INTO `tc-normas` (`id`, `norma_codigo`, `norma_nombre`, `norma_resumen`, `norma_fpublicacion`, `norma_scumplimiento`, `norma_oemisor`, `norma_osupervisor`, `norma_sumilla`, `norma_identificador`, `norma_cumplimiento`, `norma_clasificacion`, `norma_tipo`, `norma_estado`, `norma_estatus`, `norma_gestor`, `created_at`, `updated_at`) VALUES
	(2, '02001-R0', 'Ley de Transparencia y Acceso a la Información Pública', 'Ley de Transparencia y Acceso a la Información Pública', '2002-08-02', 1, 5, 3, 1, 'LEY Nº 27806', 3, 1, 2, 1, 'Modificado', 14, '2024-12-11 23:45:57', '2025-03-10 20:09:47'),
	(37, '16001-R0', 'Resolución SMV  Nº 020-2016-SMV/01', 'El Expediente N° 2016021756, el Informe Conjunto N° 528-2016-SMV/06/12/13 del 07 de julio de 2016, emitido por la Oficina de Asesoría Jurídica, la Superintendencia Adjunta de Investigación y Desarrollo y la Superintendencia Adjunta de Riesgos; así como el proyecto de Normas para la \r\nDifusión de Información al Mercado de Valores a través de la Página Web Corporativa de las Sociedades Emisoras (en adelante, el PROYECTO).', '2016-07-11', 1, 3, 2, 1, '020-2016-SMV/01', 3, 1, 1, 1, 'Vigente', 14, '2024-12-18 14:34:01', '2025-02-27 20:33:21'),
	(38, '17001-R0', 'DECRETO LEGISLATIVO Nº 1353', 'El presente Decreto Legislativo tiene por objeto crear la Autoridad Nacional de Transparencia y Acceso a la Información Pública, fortalecer el Régimen de Protección de Datos Personales y la regulación de la gestión de intereses. \r\nLas normas contenidas en el presente Decreto Legislativo son aplicables a todas las entidades señaladas en el Artículo I del Título Preliminar de la Ley N° 27444, Ley del Procedimiento Administrativo General; así como a las empresas del Estado, personas naturales y jurídicas de derecho privado, en lo que corresponda; y a las personas comprendidas en la Ley N° 29733, Ley de Protección de Datos Personales.', '2017-01-07', 1, 1, 2, 1, 'DECRETO LEGISLATIVO Nº 1353', 1, 1, 2, 3, 'Modificado', 14, '2024-12-18 15:11:54', '2025-02-27 20:27:52'),
	(39, '17002-R0', 'Decreto Legislativo que  crea la Autoridad Nacional de Transparencia  y Acceso a la Información Pública, fortalece  el Régimen de Protección de Datos  Personales y la regulación de la gestión de  intereses', 'Apruébase el Reglamento del Decreto Legislativo Nº 1353, Decreto Legislativo que crea la Autoridad Nacional de Transparencia y Acceso a la Información Pública, fortalece el Régimen de Protección de Datos Personales y la regulación de la gestión de intereses El presente Decreto Supremo y el Reglamento aprobado en el artículo precedente, serán publicados en el diario oficial El Peruano, en el Portal del Estado Peruano (www.peru.gob.pe) y, en el Portal Institucional del Ministerio de Justicia y Derechos Humanos (www.minjus.gob.pe).', '2017-09-15', 1, 1, 1, 1, 'N° 019-2017-JUS', 3, 1, 2, 5, 'Vigente', 14, '2024-12-18 17:31:23', '2025-02-27 20:20:44'),
	(40, '17003-R0', 'Lineamientos para la Implementacion del Portal de Transparencia Estandar en las Entidades de la Administracion Pública', '-', '2017-02-18', 1, 1, 1, 1, 'Directiva N° 001-2017-PCM/SGP', 2, 1, 1, 1, 'Aprobado', 14, '2024-12-18 22:54:03', '2025-02-27 20:21:34'),
	(41, '19001-R0', 'DECRETO SUPREMO N° 021-2019-JUS', 'Que, mediante Ley Nº 27806, Ley de Transparencia y Acceso a la Información Pública, se promueve la transparencia de los actos del Estado y regula el derecho fundamental del acceso a la información pública consagrado en el numeral 2 del artículo 5 de la Constitución Política del Perú; \r\nQue, mediante Ley N° 27927, Ley que modifica la Ley N° 27806, Ley de Transparencia y Acceso a la Información Pública, se modifican e incorporan varios artículos a la Ley Nº 27806; Que, con Decreto Supremo N° 043-2003-PCM, se aprueba el Texto Único Ordenado de la Ley Nº 27806, Ley de Transparencia y Acceso a la Información Pública; \r\nQue, mediante Ley N° 29239, Ley sobre medidas de control de sustancias químicas susceptibles de empleo para la fabricación de armas químicas, se incorpora el inciso f) en el numeral 1 del artículo 16 del Texto Único rdenado de la Ley N° 27806;', '2019-12-11', 1, 1, 4, 1, 'N° 021-2019-JUS', 1, 1, 2, 1, 'Vigente', 14, '2024-12-19 00:00:15', '2025-02-27 20:09:33'),
	(42, '18001-R0', 'Lineamiento de transparencia en la gestión de las  Empresas bajo el ámbito de FONAFE', '-', '2018-03-15', 1, 1, 1, 1, '018-2018/DE-FONAFE', 3, 1, 1, 1, 'Vigente', 14, '2024-12-19 15:06:52', '2025-02-27 20:16:55'),
	(43, '24001-R0', 'Decreto Supremo que Aprueba el Reglamento de la Ley de Transparencia y Acceso a la Información Pública', 'Que, el artículo 1 de la Ley Nº 27806, Ley de Transparencia y Acceso a la Información Pública, señala que tiene la finalidad de promover la transparencia de los actos del Estado y regular el derecho fundamental del acceso a la información pública consagrado en el numeral 5 del artículo 2 de la Constitución Política del Perú; \r\nQue, mediante Decreto Supremo N° 072-2003-PCM, se aprobó el Reglamento de la Ley de Transparencia y Acceso a la Información Pública, el cual regula la aplicación de las normas y la ejecución de los procedimientos establecidos en \r\nla ley antes señalada;\r\nQue, conforme lo disponen los incisos l) y r) del artículo 7 de la Ley N° 29809, Ley de Organización y Funciones del Ministerio de Justicia y Derechos Humanos, son funciones específi cas del Ministerio de Justicia y Derechos Humanos, entre otras, estudiar y proponer la dación y reforma de la legislación, así como otras que se establezcan por ley;', '2024-05-16', 1, 1, 1, 1, 'N° 007-2024-JUS', 3, 1, 2, 1, 'Vigente', 14, '2024-12-19 17:32:23', '2025-03-18 00:00:21'),
	(44, '03001-R0', 'Ley que modifica la Ley Nº 27806, Ley de Transparencia y Acceso a la Información Pública', 'Ley que modifica la Ley Nº 27806, Ley de Transparencia y Acceso a la Información Pública', '2003-02-04', 1, 1, 1, 1, '27927', 3, 1, 2, 3, 'Vigente', 14, '2025-01-16 21:03:15', '2025-02-27 21:32:15'),
	(68, '12001-R0', 'Ley General de la Persona con Discapacidad', 'Ley General de la Persona con Discapacidad', '2012-12-24', 1, 1, 3, 1, 'LEY Nº 29973', 3, 1, 1, 3, 'Vigente', 14, '2025-02-21 00:01:58', '2025-02-27 20:44:11'),
	(69, '18002-R0', 'Decreto Legislativo que fortalece el Tribunal de Transparencia y Acceso a la Información Pública', 'Decreto Legislativo que fortalece el Tribunal de Transparencia y Acceso a la Información Pública', '2018-09-13', 1, 6, 4, 1, 'DECRETO LEGISLATIVO Nº 1416', 3, 1, 2, 3, 'Vigente', 14, '2025-02-25 23:40:41', '2025-02-27 20:11:34'),
	(70, '19002-R0', 'Ley que modifica la Ley 27806, Ley de Transparencia y Acceso a la Información Pública, respecto a la transparencia en el Poder Judicial, el Ministerio Público, la Junta Nacional de Justicia, el Tribunal Constitucional y la Academia de la Magistratura', 'Ley que modifica la Ley 27806, Ley de Transparencia y Acceso a la Información Pública, respecto a la transparencia en el Poder Judicial, el Ministerio Público, la Junta Nacional de Justicia, el Tribunal Constitucional y la Academia de la Magistratura', '2019-04-24', 1, 1, 1, 1, 'LEY Nº 30934', 1, 1, 2, 3, 'Vigente', 14, '2025-02-26 01:22:52', '2025-02-27 20:10:54'),
	(71, '08001-R0', 'Lineamientos para la uniformización del contenido de los portales de transparencia de las entidades públicas', 'Aprueban Directiva Nº 004-2008-PCM/SGP “Lineamientos para la uniformización del contenido de los portales de transparencia de las entidades públicas”\r\nRESOLUCION MINISTERIAL Nº 398-2008-PCM', '2008-12-05', 1, 6, 1, 1, 'Directiva Nº 004-2008-PCM/SGP', 3, 1, 2, 1, 'Derogado', 14, '2025-02-26 22:31:07', '2025-02-27 21:10:07'),
	(73, '10001-R0', 'Lineamientos para la implementación del Portal de Transparencia Estándar en las entidades de la Administración Pública', 'Aprueban Directiva “Lineamientos para la implementación del Portal de Transparencia Estándar en las entidades de la Administración Pública”\r\nRESOLUCION MINISTERIAL Nº 200-2010-PCM(*)', '2010-06-24', 1, 6, 1, 1, 'DIRECTIVA Nº 01-2010-PCM-SGP', 3, 1, 2, 1, 'Derogado', 14, '2025-02-26 23:15:01', '2025-02-27 20:57:06'),
	(74, '12002-R0', 'Modifican Directiva sobre “Lineamientos para la implementación del Portal de Transparencia Estándar en las Entidades de la Administración Pública”', 'RESOLUCION MINISTERIAL Nº 203-2012-PCM', '2012-08-11', 1, 6, 1, 1, 'RESOLUCION MINISTERIAL Nº 203-2012-PCM', 3, 1, 2, 3, 'Vigente', 14, '2025-02-26 23:31:11', '2025-02-27 20:46:04'),
	(75, '13001-R0', 'Modifican Directiva Nº 001-2010-PCM-SGP, Lineamientos para la implementación del Portal de Transparencia Estándar en las Entidades de la Administración Pública', 'Modifican Directiva Nº 001-2010-PCM-SGP, Lineamientos para la implementación del Portal de Transparencia Estándar en las Entidades de la Administración Pública', '2013-10-04', 1, 6, 1, 1, 'RESOLUCION MINISTERIAL Nº 252-2013-PCM', 3, 1, 2, 3, 'Vigente', 14, '2025-02-27 00:35:08', '2025-02-27 20:38:19'),
	(77, '10002-R0', 'Lineamientos para la implementación del Portal de Transparencia Estándar en las entidades de la Administración Pública', 'Aprueban Directiva “Lineamientos para la implementación del Portal de Transparencia Estándar en las entidades de la Administración Pública”\r\nRESOLUCION MINISTERIAL Nº 200-2010-PCM(*)', '2010-06-25', 1, 6, 1, 1, 'RESOLUCION MINISTERIAL Nº 200-2010-PCM', 3, 1, 2, 3, 'Vigente', 14, '2025-02-27 01:29:44', '2025-02-27 20:46:58'),
